const NATIVE35={};
function loadNative35(kind){
  const isAB=kind==='ab',globalKey=isAB?'comprasNative35':'housekeepingNative35',src=isAB?'assets/js/modules/compras-ab-native-v35.js':'assets/js/modules/housekeeping-native-v35.js';
  if(window.VG?.[globalKey])return Promise.resolve(window.VG[globalKey]);
  if(NATIVE35[kind])return NATIVE35[kind];
  NATIVE35[kind]=new Promise((resolve,reject)=>{const existing=document.querySelector(`script[data-vg-native35="${kind}"]`);if(existing){existing.addEventListener('load',()=>resolve(window.VG?.[globalKey]));existing.addEventListener('error',()=>reject(new Error('Falha ao carregar '+kind)));return;}const sc=document.createElement('script');sc.src=src;sc.async=true;sc.dataset.vgNative35=kind;sc.onload=()=>window.VG?.[globalKey]?resolve(window.VG[globalKey]):reject(new Error('Módulo '+kind+' não se registou.'));sc.onerror=()=>reject(new Error('Falha ao carregar '+src));document.head.appendChild(sc);}).catch(e=>{delete NATIVE35[kind];throw e;});
  return NATIVE35[kind];
}

const HOTEL_ALIASES={
 'C TOMAR':'COLLECTION TOMAR','TOMAR':'COLLECTION TOMAR','VILA GALE COLLECTION TOMAR':'COLLECTION TOMAR',
 'PALACIO ARCOS':'COLLECTION PALACIO DOS ARCOS','PALACIO DOS ARCOS':'COLLECTION PALACIO DOS ARCOS','VILA GALE COLLECTION PALACIO DOS ARCOS':'COLLECTION PALACIO DOS ARCOS',
 'C SINTRA':'COLLECTION SINTRA','VILA GALE COLLECTION SINTRA':'COLLECTION SINTRA','OPERA':'OPERA','ÓPERA':'OPERA',
 'DOUROVINEYARDS':'DOURO VINEYARDS','VILA GALE DOURO VINEYARDS':'DOURO VINEYARDS','SERRA ESTRELA':'COLLECTION SERRA DA ESTRELA',
 'VIL GAL COL FIG DA FOZ':'COLLECTION FIGUEIRA DA FOZ','VIL GAL COL PON DE LIM':'COLLECTION PONTE DE LIMA VINEYARDS',
 'C S MIGUEL':'COLLECTION S. MIGUEL','SAO MIGUEL':'COLLECTION S. MIGUEL','S MIGUEL':'COLLECTION S. MIGUEL'
};
function canonHotel(v){
  let x=norm(v).replace(/^VILA GALE /,'').replace(/^VG /,'').replace(/ HOTEL$/,'').trim();
  if(HOTEL_ALIASES[x])x=HOTEL_ALIASES[x];
  try{const c=window.VG?.market?.canonicalHotel?.(x);if(c)return c;}catch(e){}
  return x;
}
function isCurrentHotel(h){try{return !window.VG?.market||window.VG.market.isCurrentHotel(h);}catch(e){return true;}}
function allowedHotel(h){const u=user();if(!u)return false;if(direction())return true;if(typeof window.vgAuthCanAccessHotel==='function')return window.vgAuthCanAccessHotel(h);const hs=Array.isArray(u.hotels)?u.hotels:(u.hotel?[u.hotel]:[]);return hs.some(x=>canonHotel(h)===canonHotel(x));}
function hotelRegion(h){try{for(const[k,arr] of Object.entries(REGIOES||{}))if((arr||[]).some(x=>canonHotel(x)===canonHotel(h)))return window.VG?.market?.regionLabel?.(k)||k;}catch(e){}return '—';}

const state={seed:null,ready:false,repTab:'executive',weekly:{hotel:'',reportId:''},semester:{periods:[],selectedId:null,subtab:'overview',dimension:'categories',region:'Todas',hotel:'Todas',loadedAt:null},ab:{imports:[],selected:null,recipeMap:{}},recipes:{query:'',kind:'all',page:1,pageSize:36},theoretical:{cacheKey:'',data:null},buffet:{rows:[],sourceFile:'',loadedAt:null,hotel:'Todas',meal:'Todos'},hk:{tab:'exact',db:null},cross:[]};

async function loadSeed(){
  if(state.seed)return state.seed;
  try{const r=await fetch('assets/data/operations-seed-v33.json',{cache:'no-store'});if(!r.ok)throw Error('HTTP '+r.status);state.seed=await r.json();return state.seed;}
  catch(e){console.warn('V33 seed indisponível',e);state.seed={weeklyReputation:{reports:[]},technicalLibrary:{recipes:[],products:[],beveragePriceMatrix:[]},detailedRevenue:[]};return state.seed;}
}

// ---------- Reputação semanal: converte o JSON da app semanal para o motor existente ----------
function weeklyReports(){return (state.seed?.weeklyReputation?.reports||[]).filter(r=>isCurrentHotel(canonHotel(r.hotelNameClean||r.hotelName||r.hotelKey))&&allowedHotel(r.hotelNameClean||r.hotelName));}
function reportToLegacy(r){
  const dm={};for(const d of r.departments||[]){const k=norm(d.name);if(k==='SERVICE'||k==='SERVICO')dm.Service={val:num(d.gri),delta:num(d.griDelta)};if(k==='ROOM'||k==='QUARTO')dm.Room={val:num(d.gri),delta:num(d.griDelta)};if(k==='CLEANLINESS'||k==='LIMPEZA')dm.Cleanliness={val:num(d.gri),delta:num(d.griDelta)};if(k==='VALUE'||k==='VALOR')dm.Value={val:num(d.gri),delta:num(d.griDelta)};if(k==='LOCATION'||k==='LOCALIZACAO')dm.Location={val:num(d.gri),delta:num(d.griDelta)};}
  const ir=(r.internalRanking||[]).find(x=>norm(x.group)==='VILA GALE')||(r.internalRanking||[])[0];
  return {hotel:canonHotel(r.hotelNameClean||r.hotelName),week:r.periodLabel||`${r.periodStart||''} - ${r.periodEnd||''}`,period:r.periodLabel||'',gri:num(r.kpis?.gri),griDelta:num(r.kpis?.griDelta),griGoal:num(r.kpis?.goal),reviews:num(r.kpis?.reviews),reviewsDelta:num(r.kpis?.reviewsDelta),depts:dm,mgmtResp:num(r.kpis?.mgmtResp),srcList:(r.sources||[]).filter(x=>norm(x.name)!=='GRI').map(x=>({name:x.name,score:num(x.index)})),cqi:num(r.competition?.cqi),rankVG:ir?`${ir.rank}/${ir.outOf}`:null,negCats:(r.negCategories||[]).map(x=>({cat:x.category,mentions:x.count,impact:x.griImpact})),posCats:(r.posCategories||[]).map(x=>({cat:x.category,mentions:x.count,impact:x.griImpact})),_v33:true};
}
function seedLegacyReputation(){
  try{
    if(typeof REP_STORE==='undefined')return;
    if(Object.values(REP_STORE).some(a=>Array.isArray(a)&&a.some(x=>x?._v33)))return;
    for(const r of weeklyReports()){
      const e=reportToLegacy(r);if(!e.hotel||e.gri==null)continue;const k=(typeof rtKey==='function'?rtKey(e.hotel):norm(e.hotel).toLowerCase());REP_STORE[k]=REP_STORE[k]||[];
      const ix=REP_STORE[k].findIndex(x=>(x.period||x.week)===(e.period||e.week));if(ix>=0)REP_STORE[k][ix]=e;else REP_STORE[k].push(e);
    }
    if(typeof rtNormalizeStore==='function')rtNormalizeStore();if(typeof rtRender==='function')rtRender();
  }catch(e){console.warn('seed reputation',e);}
}
function repLatestByHotel(){
  const mp=new Map();for(const r of weeklyReports()){const h=canonHotel(r.hotelNameClean||r.hotelName);const d=Date.parse(r.periodEnd||r.createdAt||'')||0;if(!mp.has(h)||d>mp.get(h)._d)mp.set(h,Object.assign({_d:d},r));}return [...mp.entries()].map(([hotel,r])=>({hotel,r}));
}
function repExecutiveHtml(){
  const rows=repLatestByHotel().sort((a,b)=>(num(b.r.kpis?.gri)||0)-(num(a.r.kpis?.gri)||0));if(!rows.length)return emptyCard('Sem dados semanais','Importe o JSON semanal ou PDFs ReviewPro.');
  const avg=sum(rows,x=>x.r.kpis?.gri)/rows.length,resp=sum(rows,x=>x.r.kpis?.mgmtResp)/rows.length,below=rows.filter(x=>num(x.r.kpis?.goal)!=null&&num(x.r.kpis?.gri)<num(x.r.kpis?.goal)).length;
  const cats={};rows.forEach(({r})=>(r.negCategories||[]).forEach(c=>{const k=c.category||'Outros';cats[k]=(cats[k]||0)+(Number(c.count)||0);}));const topCats=Object.entries(cats).sort((a,b)=>b[1]-a[1]).slice(0,6);
  return `<div class="od-kpis"><article><span>GRI médio</span><strong>${fmt(avg,1)}%</strong><small>${rows.length} unidades com leitura</small></article><article><span>Resposta média</span><strong>${fmt(resp,1)}%</strong><small>Management response</small></article><article class="${below?'warn':''}"><span>Abaixo da meta</span><strong>${below}</strong><small>Última semana disponível</small></article><article><span>Melhor GRI</span><strong>${fmt(rows[0].r.kpis?.gri,1)}%</strong><small>${esc(rows[0].hotel)}</small></article></div>
  <div class="od-grid2"><section class="od-card"><header><h3>Ranking semanal</h3><span>última leitura por hotel</span></header><div class="od-table-scroll"><table><thead><tr><th>#</th><th>Hotel</th><th>GRI</th><th>Δ</th><th>Meta</th><th>Reviews</th><th>Resposta</th><th>CQI</th></tr></thead><tbody>${rows.map((x,i)=>`<tr><td>${i+1}</td><td>${esc(x.hotel)}</td><td class="${num(x.r.kpis?.gri)>=90?'good':num(x.r.kpis?.gri)>=80?'warn':'bad'}">${fmt(x.r.kpis?.gri,1)}%</td><td>${signed(x.r.kpis?.griDelta,' p.p.')}</td><td>${num(x.r.kpis?.goal)==null?'—':fmt(x.r.kpis.goal,1)+'%'}</td><td>${fmt(x.r.kpis?.reviews,0)}</td><td>${fmt(x.r.kpis?.mgmtResp,1)}%</td><td>${fmt(x.r.competition?.cqi,1)}</td></tr>`).join('')}</tbody></table></div></section>
  <section class="od-card"><header><h3>Pressão negativa</h3><span>categorias mais mencionadas</span></header><div class="od-bars">${topCats.map(([k,v])=>bar(k,v,topCats[0]?.[1]||1,'bad')).join('')||'<p class="muted">Sem categorias negativas.</p>'}</div></section></div>`;
}
function repHotelHtml(){
  const rows=repLatestByHotel().sort((a,b)=>a.hotel.localeCompare(b.hotel,'pt'));if(!rows.length)return emptyCard('Sem dados','');
  const options=rows.map(x=>`<option value="${esc(x.hotel)}">${esc(x.hotel)}</option>`).join('');
  return `<section class="od-card"><header><h3>Ficha de reputação da unidade</h3><span>semana + concorrência + semântica</span></header><label class="od-field">Hotel<select id="rep33Hotel">${options}</select></label><div id="rep33HotelBody"></div></section>`;
}
function renderRepHotelBody(){
  const el=document.getElementById('rep33HotelBody'),sel=document.getElementById('rep33Hotel');if(!el||!sel)return;
  const h=sel.value, history=weeklySortedReports(h), r=history[0];
  if(!r){el.innerHTML='';return;}
  const historyRows=history.slice(0,26).map(x=>`<tr><td>${esc(x.periodLabel||x.periodEnd||'—')}</td><td>${fmt(x.kpis?.gri,1)}%</td><td>${signed(x.kpis?.griDelta,' p.p.')}</td><td>${fmt(x.kpis?.reviews,0)}</td><td>${fmt(x.kpis?.mgmtResp,1)}%</td><td>${fmt(x.competition?.cqi,1)}</td></tr>`).join('');
  el.innerHTML=`${repDetailedBody(r)}<section class="od-card"><header><h3>Histórico semanal</h3><span>até 26 leituras</span></header><div class="od-table-scroll"><table><thead><tr><th>Semana</th><th>GRI</th><th>Δ</th><th>Reviews</th><th>Resposta</th><th>CQI</th></tr></thead><tbody>${historyRows}</tbody></table></div></section>`;
}
function weeklySortedReports(hotel){
  return weeklyReports().filter(r=>!hotel||canonHotel(r.hotelNameClean||r.hotelName)===canonHotel(hotel))
    .slice().sort((a,b)=>(Date.parse(b.periodEnd||b.createdAt||'')||0)-(Date.parse(a.periodEnd||a.createdAt||'')||0));
}
