function semSemantics(p){const scope=semScopeSet(p),key=state.semester.dimension||'categories',rows=semGroup(p.semantic?.[key]||[],'name','positive','mentions',scope);return `<section class="od-card"><header><h3>Semântica</h3><span>volume e percentagem positiva</span></header><div class="od-chiprow">${[['categories','Categorias'],['sources','Fontes'],['languages','Idiomas'],['countries','Países'],['tripTypes','Tipo de viagem']].map(([k,l])=>`<button class="od-chip ${key===k?'active':''}" data-semdim="${k}">${l}</button>`).join('')}</div><div class="od-table-scroll"><table><thead><tr><th>Dimensão</th><th>Menções</th><th>Positivas</th><th>Negativas</th></tr></thead><tbody>${rows.slice(0,100).map(x=>`<tr><td>${esc(x.name)}</td><td>${fmt(x.count,0)}</td><td>${fmt(x.value,1)}%</td><td>${fmt(semWeighted(x.rows,'negative','mentions'),1)}%</td></tr>`).join('')}</tbody></table></div></section>`;}
function semCompetition(p){const rows=semScopeHotels(p).filter(x=>x.cqi!=null).sort((a,b)=>(b.cqi||0)-(a.cqi||0));return `<section class="od-card"><header><h3>Concorrência &amp; CQI</h3><span>posição face ao compset</span></header><div class="od-table-scroll"><table><thead><tr><th>Unidade</th><th>GRI</th><th>Compset</th><th>Dif. p.p.</th><th>CQI</th><th>Δ CQI</th><th>Ranking</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${esc(r.hotel)}</td><td>${fmt(r.gri,1)}%</td><td>${fmt(r.compset,1)}%</td><td>${signed((r.gri??0)-(r.compset??0),' p.p.')}</td><td><b>${fmt(r.cqi,1)}</b></td><td>${signed(r.cqiChange,'')}</td><td>${esc(r.compRank||'—')}</td></tr>`).join('')}</tbody></table></div></section>`;}
function semResponses(p){const rows=semScopeHotels(p).filter(x=>x.responseRatio!=null).sort((a,b)=>(b.responseRatio||0)-(a.responseRatio||0)),scope=semScopeSet(p),src=semGroup(p.responseSources,'source','ratio','respondable',scope);return `<div class="od-grid2"><section class="od-card"><header><h3>Gestão de respostas por unidade</h3></header><div class="od-table-scroll"><table><thead><tr><th>Unidade</th><th>Taxa</th><th>Respondidas</th><th>Respondíveis</th><th>Tempo médio</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${esc(r.hotel)}</td><td>${fmt(r.responseRatio,1)}%</td><td>${fmt(r.responded,0)}</td><td>${fmt(r.respondable,0)}</td><td>${r.avgDays==null?'—':fmt(r.avgDays,1)+' d'}</td></tr>`).join('')}</tbody></table></div></section><section class="od-card"><header><h3>Por fonte</h3></header><div class="od-bars">${src.map(x=>bar(x.name,x.value||0,100,(x.value||0)>=95?'good':(x.value||0)>=85?'warn':'bad',fmt(x.value,1)+'%')).join('')}</div></section></div>`;}
function semMentions(p){const scope=semScopeSet(p),rows=(p.mentions||[]).filter(x=>scope.has(x.hotel)),g={};for(const x of rows){const k=x.category||x.subconcept||x.keyword||'Outros';const z=g[k]||(g[k]={name:k,total:0,pos:0,neg:0});z.total++;if(semNorm(x.sentiment)==='positive')z.pos++;if(semNorm(x.sentiment)==='negative')z.neg++;}const cats=Object.values(g).sort((a,b)=>b.total-a.total);return `<div class="od-kpis compact"><article><span>Menções detalhadas</span><strong>${fmt(rows.length,0)}</strong><small>${rows.length?'carregadas nesta sessão':'reimporte o ficheiro para detalhe'}</small></article><article><span>Positivas</span><strong>${fmt(rows.filter(x=>semNorm(x.sentiment)==='positive').length,0)}</strong><small>classificação ReviewPro</small></article><article><span>Negativas</span><strong>${fmt(rows.filter(x=>semNorm(x.sentiment)==='negative').length,0)}</strong><small>foco operacional</small></article></div><section class="od-card"><header><h3>Temas das menções</h3><span>Top 100</span></header>${rows.length?`<div class="od-table-scroll"><table><thead><tr><th>Categoria</th><th>Total</th><th>Positivas</th><th>Negativas</th></tr></thead><tbody>${cats.slice(0,100).map(x=>`<tr><td>${esc(x.name)}</td><td>${x.total}</td><td>${x.pos}</td><td>${x.neg}</td></tr>`).join('')}</tbody></table></div>`:'<p class="muted">O ficheiro de menções detalhadas não está carregado nesta sessão. As restantes análises semestrais continuam disponíveis.</p>'}</section>`;}
function semCompare(p){const other=(state.semester.periods||[]).filter(x=>x.id!==p.id)[0];if(!other)return emptyCard('Sem outro semestre','Importe outro período para comparar.');const a=semAgg(p),b=semAgg(other),metrics=[['GRI',a.gri,b.gri,'%'],['Avaliações',a.reviews,b.reviews,''],['Menções positivas',a.positive,b.positive,'%'],['Resposta',a.responseRatio,b.responseRatio,'%'],['CQI',a.cqi,b.cqi,'']];const bh=new Map((other.hotels||[]).map(x=>[x.hotel,x]));return `<div class="od-kpis">${metrics.map(([l,x,y,u])=>`<article><span>${l}</span><strong>${fmt(x,1)}${u}</strong><small>${signed((x??0)-(y??0),u==='%'?' p.p.':'')}</small></article>`).join('')}</div><section class="od-card"><header><h3>${esc(p.label)} vs ${esc(other.label)}</h3></header><div class="od-table-scroll"><table><thead><tr><th>Unidade</th><th>GRI atual</th><th>GRI comparado</th><th>Δ</th><th>Avaliações</th><th>Δ avaliações</th></tr></thead><tbody>${semScopeHotels(p).map(r=>{const o=bh.get(r.hotel);return`<tr><td>${esc(r.hotel)}</td><td>${fmt(r.gri,1)}%</td><td>${fmt(o?.gri,1)}%</td><td>${signed((r.gri??0)-(o?.gri??0),' p.p.')}</td><td>${fmt(r.reviews,0)}</td><td>${signed((r.reviews??0)-(o?.reviews??0),'')}</td></tr>`;}).join('')}</tbody></table></div></section>`;}
function semPersistable(){semMigrate();return{...state.semester,periods:(state.semester.periods||[]).map(p=>({...p,mentions:[]}))};}
async function rep33LoadSemester(files){if(!files?.length)return;try{await window.VG?.performance?.ensureXLSX?.();const grouped=new Map();for(const file of [...files]){const ab=await file.arrayBuffer(),wb=XLSX.read(ab,{type:'array',cellDates:false}),book={file:file.name,sheets:{}};for(const sn of wb.SheetNames)book.sheets[sn]=XLSX.utils.sheet_to_json(wb.Sheets[sn],{header:1,defval:null,raw:true});const role=semDetectRole(file.name,book);if(!role)throw Error(`Não foi possível identificar ${file.name}`);const meta=semDateMeta(book),g=grouped.get(meta.id)||{meta,files:{},fileMeta:[]};g.files[role]=book;g.fileMeta.push({role,name:file.name,sheets:wb.SheetNames});grouped.set(meta.id,g);}semMigrate();for(const g of grouped.values()){const prev=state.semester.periods.find(x=>x.id===g.meta.id),mergedFiles={};if(prev?._rawFiles)Object.assign(mergedFiles,prev._rawFiles);Object.assign(mergedFiles,g.files);const p=semBuildPeriod(g.meta,mergedFiles,g.fileMeta);if(prev){p.files=[...(prev.files||[]).filter(x=>!g.fileMeta.some(n=>n.role===x.role)),...g.fileMeta];if(!g.files.results){p.hotels=prev.hotels||p.hotels;p.departments=prev.departments||[];p.sources=prev.sources||[];}if(!g.files.semantic){p.semantic=prev.semantic||p.semantic;}if(!g.files.responses){p.hotels=(p.hotels||[]).map(h=>Object.assign({},(prev.hotels||[]).find(x=>x.hotel===h.hotel)||{},h));p.responseSources=prev.responseSources||[];}if(!g.files.competition){p.hotels=(p.hotels||[]).map(h=>Object.assign({},(prev.hotels||[]).find(x=>x.hotel===h.hotel)||{},h));}if(!g.files.panel)p.daily=prev.daily||[];if(!g.files.mentions)p.mentions=prev.mentions||[];}Object.defineProperty(p,'_rawFiles',{value:mergedFiles,writable:true,enumerable:false});const ix=state.semester.periods.findIndex(x=>x.id===p.id);if(ix>=0)state.semester.periods[ix]=p;else state.semester.periods.push(p);state.semester.selectedId=p.id;}state.semester.loadedAt=new Date().toISOString();persistLocal();renderReputation33();toast(`Reputação semestral: ${grouped.size} período(s) processado(s).`);}catch(e){console.error(e);toast('Erro na importação semestral: '+e.message,true);}}
function repSemesterHtml(){semMigrate();const p=semCurrent();if(!p)return `<section class="od-card od-empty"><div class="od-empty-icon">◫</div><h3>Reputação semestral</h3><p>Carregue os seis ficheiros ReviewPro. O motor reconhece Painel, Resultados, Concorrência, Respostas, Semântica Resultados e Semântica Menções pelo conteúdo.</p><label class="od-btn primary">Importar ficheiros<input id="rep33SemesterInput" type="file" accept=".xlsx,.xls" multiple hidden></label></section>`;const regs=['Todas',...new Set((p.hotels||[]).map(x=>hotelRegion(x.hotel)).filter(x=>x&&x!=='—'))],hs=(p.hotels||[]).filter(x=>state.semester.region==='Todas'||hotelRegion(x.hotel)===state.semester.region);const body=state.semester.subtab==='overview'?semOverview(p):state.semester.subtab==='units'?semUnits(p):state.semester.subtab==='departments'?semDepartments(p):state.semester.subtab==='semantics'?semSemantics(p):state.semester.subtab==='competition'?semCompetition(p):state.semester.subtab==='responses'?semResponses(p):state.semester.subtab==='mentions'?semMentions(p):semCompare(p);return `<div class="od-toolbar"><label>Semestre<select id="sem33Period">${state.semester.periods.map(x=>`<option value="${x.id}" ${x.id===p.id?'selected':''}>${esc(x.label)}</option>`).join('')}</select></label><label>Região<select id="sem33Region">${regs.map(x=>`<option ${x===state.semester.region?'selected':''}>${esc(x)}</option>`).join('')}</select></label><label>Unidade<select id="sem33Hotel"><option>Todas</option>${hs.map(x=>`<option ${x.hotel===state.semester.hotel?'selected':''}>${esc(x.hotel)}</option>`).join('')}</select></label><label class="od-btn">Atualizar ficheiros<input id="rep33SemesterInput" type="file" accept=".xlsx,.xls" multiple hidden></label></div><div class="od-help"><b>${esc(p.label)}</b> · ${esc(p.range)} · ${(p.files||[]).map(x=>`${SEM_ROLES[x.role]||x.role}: ${x.name}`).join(' · ')}</div><nav class="od-subtabs">${[['overview','Executivo'],['units','Unidades'],['departments','Departamentos'],['semantics','Semântica'],['competition','Concorrência'],['responses','Respostas'],['mentions','Menções'],['compare','Comparar']].map(([k,l])=>`<button data-semtab="${k}" class="${state.semester.subtab===k?'active':''}">${l}</button>`).join('')}</nav>${body}`;}

function bindSemesterUI(){
  document.getElementById('rep33SemesterInput')?.addEventListener('change',e=>rep33LoadSemester(e.target.files));
  document.getElementById('sem33Period')?.addEventListener('change',e=>{state.semester.selectedId=e.target.value;state.semester.hotel='Todas';persistLocal();renderReputation33();});
  document.getElementById('sem33Region')?.addEventListener('change',e=>{state.semester.region=e.target.value;state.semester.hotel='Todas';renderReputation33();});
  document.getElementById('sem33Hotel')?.addEventListener('change',e=>{state.semester.hotel=e.target.value;renderReputation33();});
  document.querySelectorAll('[data-semtab]').forEach(b=>b.onclick=()=>{state.semester.subtab=b.dataset.semtab;renderReputation33();});
  document.querySelectorAll('[data-semdim]').forEach(b=>b.onclick=()=>{state.semester.dimension=b.dataset.semdim;renderReputation33();});
  document.querySelectorAll('[data-semhotel]').forEach(b=>b.onclick=()=>{state.semester.hotel=b.dataset.semhotel;state.semester.subtab='units';renderReputation33();});
}
function renderReputation33(){
  const root=document.getElementById('repV33Root');if(!root)return;
  const body=state.repTab==='executive'?repExecutiveHtml():state.repTab==='weekly'?repWeeklyHtml():state.repTab==='semester'?repSemesterHtml():repHotelHtml();
  root.innerHTML=`<div class="od-hero"><div><span class="eyebrow">Guest Experience</span><h2>Reputação &amp; Guest Experience</h2><p>Visão executiva, leitura semanal completa por origem, análise semestral e ficha histórica por hotel.</p></div><div class="od-actions"><label class="od-btn">Importar JSON semanal<input id="rep33JsonInput" type="file" accept=".json" hidden></label></div></div>
  <nav class="od-tabs"><button data-reptab="executive" class="${state.repTab==='executive'?'active':''}">Visão Executiva</button><button data-reptab="weekly" class="${state.repTab==='weekly'?'active':''}">Semanal</button><button data-reptab="semester" class="${state.repTab==='semester'?'active':''}">Semestral</button><button data-reptab="hotel" class="${state.repTab==='hotel'?'active':''}">Hotel</button></nav><div id="rep33Body">${body}</div>`;
  const legacy=document.querySelector('#view-reputacao .view-rep-root');if(legacy)legacy.style.display='none';
  root.querySelectorAll('[data-reptab]').forEach(b=>b.onclick=()=>{state.repTab=b.dataset.reptab;renderReputation33();});
  document.getElementById('rep33JsonInput')?.addEventListener('change',e=>rep33LoadJson(e.target.files[0]));
  document.getElementById('rep33Hotel')?.addEventListener('change',renderRepHotelBody);
  if(state.repTab==='hotel')setTimeout(renderRepHotelBody,0);
  if(state.repTab==='weekly')bindWeeklyUI();
  if(state.repTab==='semester')bindSemesterUI();
}
async function rep33LoadJson(file){if(!file)return;try{const d=JSON.parse(await file.text());if(!Array.isArray(d.reports))throw Error('Formato vg_reputation inválido');state.seed.weeklyReputation=d;seedLegacyReputation();renderReputation33();toast(`${d.reports.length} relatórios semanais carregados.`);}catch(e){toast(e.message,true);}}

