function ensureRevenueSeed(){try{if(typeof RD_STORE==='undefined'||RD_STORE.length)return;const list=(state.seed?.detailedRevenue||[]).map(s=>Object.assign({},s,{rows:(s.rows||[]).filter(r=>isCurrentHotel(r.hotel)&&allowedHotel(r.hotel))})).filter(s=>s.rows.length);RD_STORE.push(...list);if(typeof rdUpdateUI==='function')rdUpdateUI();}catch(e){console.warn(e);}}
function installRevenueView(){const root=document.getElementById('receitasDetalheRoot');if(!root||root.dataset.ready)return;root.dataset.ready='1';root.innerHTML=`<div class="od-hero"><div><span class="eyebrow">Revenue Drill-down</span><h2>Receita Detalhada</h2><p>Do total do hotel até ponto de venda, família, subfamília, grupo e artigo.</p></div><div class="od-actions"><label class="od-btn primary">Importar Excel<input id="rd33Input" type="file" accept=".xlsx,.xls" hidden></label><button class="od-btn" id="rd33Clear">Limpar filtros</button></div></div><div class="rd33-status"><span id="rdStatus">Sem dados</span><div id="rdSnapChips"></div></div><div id="rdEmpty" class="od-empty"><div class="od-empty-icon">↗</div><h3>Sem detalhe de receitas</h3><p>Carregue o mapa de Receitas Detalhe. Se o ficheiro não tiver mês/ano, a aplicação pede o período em vez de inventar datas.</p></div><div id="rdMain" style="display:none"><div class="od-filtergrid"><label>Região<select id="rdRegiao"><option value="">Todas</option></select></label><label>Hotel<select id="rdHotel" multiple size="3"></select></label><label>Período<select id="rdPeriodo"><option value="">Todos</option></select></label><label>Família<select id="rdFamilia"><option value="">Todas</option></select></label><label>Subfamília<select id="rdSubFamilia"><option value="">Todas</option></select></label><label>Grupo<select id="rdGrupo"><option value="">Todos</option></select></label><label>Ponto de venda<select id="rdArmazem"><option value="">Todos</option></select></label></div><div id="rdActiveBadges" class="od-badges" style="display:none"><div id="rdBadgeList"></div></div><div id="rdKpis" class="od-kpis"></div><div class="od-grid2"><section class="od-card"><header><h3>Receita por ponto de venda</h3></header><div class="od-chart"><canvas id="rdChartPdV"></canvas></div></section><section class="od-card"><header><h3>Receita por família</h3></header><div class="od-chart"><canvas id="rdChartFamilia"></canvas></div></section><section class="od-card"><header><h3>Grupos</h3></header><div class="od-chart"><canvas id="rdChartGrupo"></canvas></div></section><section class="od-card"><header><h3>Artigos</h3></header><div class="od-chart"><canvas id="rdChartArtigo"></canvas></div></section></div><div style="display:none"><canvas id="rdChartEvolucao"></canvas><canvas id="rdChartComp"></canvas><canvas id="rdChartFnB"></canvas><canvas id="rdChartSubFam"></canvas><canvas id="rdChartQtd"></canvas></div><section class="od-card"><header><h3>Artigos</h3></header><div class="od-table-scroll"><table><thead><tr><th>#</th><th>Artigo</th><th>Grupo</th><th>PdV</th><th>Qtd.</th><th>VN</th></tr></thead><tbody id="rdTableArtigosBody"></tbody></table></div></section><section class="od-card"><header><h3>Pontos de venda</h3></header><div class="od-table-scroll"><table><thead><tr><th>PdV</th><th>Qtd.</th><th>VB</th><th>VN</th><th>% VN</th></tr></thead><tbody id="rdTablePdVBody"></tbody></table></div></section></div>`;
  const reg=document.getElementById('rdRegiao');try{Object.keys(REGIOES||{}).forEach(k=>reg.insertAdjacentHTML('beforeend',`<option value="${esc(window.VG?.market?.regionLabel?.(k)||k)}">${esc(window.VG?.market?.regionLabel?.(k)||k)}</option>`));}catch(e){}
  document.getElementById('rd33Input').onchange=e=>rd33LoadFile(e.target.files[0]);document.getElementById('rd33Clear').onclick=()=>typeof rdClearFilters==='function'&&rdClearFilters();['rdRegiao','rdHotel','rdPeriodo','rdFamilia','rdSubFamilia','rdGrupo','rdArmazem'].forEach(id=>document.getElementById(id)?.addEventListener('change',()=>{if(id==='rdRegiao'&&typeof rdOnRegiaoChange==='function')rdOnRegiaoChange();else if(id==='rdHotel'&&typeof rdUpdateArmazem==='function'){rdUpdateArmazem();rdRender();rdUpdateBadges();}else {rdRender?.();rdUpdateBadges?.();}}));ensureRevenueSeed();try{rdUpdateUI();}catch(e){}
}
async function rd33LoadFile(file){if(!file)return;try{await window.VG?.performance?.ensureXLSX?.();const ab=await file.arrayBuffer(),wb=XLSX.read(ab,{type:'array'});let raws=[];for(const sn of wb.SheetNames){const a=XLSX.utils.sheet_to_json(wb.Sheets[sn],{header:1,defval:null,raw:true});const hi=a.findIndex(r=>(r||[]).some(v=>norm(v)==='HOTEL'));if(hi>=0)raws=raws.concat(raws.length?a.slice(hi+1):a.slice(hi));}if(!raws.length)throw Error('Cabeçalho HOTEL não encontrado.');const hdr=raws[0].map(x=>norm(x)),ix=(...q)=>hdr.findIndex(h=>q.some(z=>h.includes(norm(z))));const ih=ix('HOTEL'),ia=ix('ARMAZEM'),ifam=ix('FAMILIA'),isub=ix('SUB FAMILIA'),ig=ix('GRUPO'),iart=ix('ARTIGO'),iq=ix('QTD'),ivb=ix('VB'),ivn=ix('VN','VALOR LIQUIDO'),im=ix('MES','ID MES'),iy=ix('ANO');let fallbackMonth='',fallbackYear='';if(im<0||iy<0){const p=prompt('Este ficheiro não identifica claramente o período. Indique mês/ano (MM/AAAA) ou deixe vazio para manter como período não identificado:','');const m=String(p||'').match(/^(0?[1-9]|1[0-2])[\/\-](20\d{2})$/);if(m){fallbackMonth=String(Number(m[1]));fallbackYear=m[2];}}
  const rows=[];for(const r of raws.slice(1)){if(!r?.[ih])continue;const h=canonHotel(r[ih]);if(!isCurrentHotel(h)||!allowedHotel(h))continue;let mm=im>=0?String(r[im]??'').replace('.0','').trim():fallbackMonth,yy=iy>=0?String(r[iy]??'').replace('.0','').trim():fallbackYear;if(/^\d{6}$/.test(mm)){yy=yy||mm.slice(0,4);mm=String(Number(mm.slice(4)));}rows.push({hotel:h,armazem:String(r[ia]??'').trim(),familia:String(r[ifam]??'').trim(),subfamilia:String(r[isub]??'').trim(),grupo:String(r[ig]??'').trim(),artigo:String(r[iart]??'').trim(),qtd:Number(r[iq])||0,vb:Number(r[ivb])||0,vn:Number(r[ivn])||0,mes:mm,ano:yy});}if(!rows.length)throw Error('Sem linhas válidas para a geografia/perfil atual.');const label=fallbackMonth&&fallbackYear?`${fallbackMonth}/${fallbackYear}`:`${file.name} · período não identificado`;RD_STORE.push({id:Date.now(),label,rows,loadedAt:new Date().toISOString(),sourceFile:file.name});rdUpdateUI();toast(`${rows.length.toLocaleString('pt-PT')} linhas de receita carregadas.`);window.VG?.events?.emit?.('revenue-detail:changed',{});}catch(e){toast('Receita detalhada: '+e.message,true);}}

// ---------- A&B ----------
function shGrid(wb,name){const sn=wb.SheetNames.find(x=>norm(x)===norm(name));return sn?XLSX.utils.sheet_to_json(wb.Sheets[sn],{header:1,defval:null,raw:true}):null;}
function findCell(g,p,max=g?.length||0){for(let r=0;r<Math.min(max||g.length,g.length);r++)for(let c=0;c<(g[r]||[]).length;c++)if(p(g[r][c],r,c))return{r,c};return null;}
function parseAbWorkbook(wb,fileName){const D={meta:{fileName,loadedAt:new Date().toISOString()},hotels:[],summary:{},total:{},comparative:{},ratios:{food:{},bev:{}},diverse:{},stock:{initial:{},purchases:{},final:{}}};const gi=shGrid(wb,'RESUMO - INDICADORES');if(!gi)throw Error('Aba RESUMO - INDICADORES não encontrada.');const a=findCell(gi,v=>norm(v)==='HOTEL');if(!a)throw Error('Cabeçalho Hotel não encontrado.');for(let r=a.r+1;r<gi.length;r++){const h=canonHotel(gi[r]?.[a.c]);if(!h)break;if(h==='TOTAL'){const row=gi[r];D.total={fcPurch:Number(row[a.c+1])||0,fcCons:Number(row[a.c+2])||0,bcPurch:Number(row[a.c+3])||0,bcCons:Number(row[a.c+4])||0,clients:Number(row[a.c+5])||0,consPax:Number(row[a.c+6])||0,stockPax:Number(row[a.c+7])||0,stockWeight:Number(row[a.c+8])||0};break;}if(norm(h)==='CONFERENCIA')break;if(!isCurrentHotel(h)||!allowedHotel(h))continue;D.hotels.push(h);const row=gi[r];D.summary[h]={fcPurch:num(row[a.c+1]),fcCons:num(row[a.c+2]),bcPurch:num(row[a.c+3]),bcCons:num(row[a.c+4]),clients:num(row[a.c+5]),consPax:num(row[a.c+6]),stockPax:num(row[a.c+7]),stockWeight:num(row[a.c+8])};}
  const comp=findCell(gi,v=>norm(v).startsWith('COMPARATIVO'));if(comp){let b=null;for(let r=comp.r;r<Math.min(gi.length,comp.r+12)&&!b;r++)for(let c=0;c<(gi[r]||[]).length;c++)if(norm(gi[r][c])==='HOTEL'){b={r,c};break;}if(b)for(let r=b.r+1;r<gi.length;r++){const h=canonHotel(gi[r]?.[b.c]);if(!h||h==='TOTAL')break;if(!D.hotels.includes(h))continue;const row=gi[r];D.comparative[h]={food:{revenue:num(row[b.c+1]),purchases:num(row[b.c+2]),purchaseRatio:num(row[b.c+3]),consumption:num(row[b.c+4]),inventory:num(row[b.c+5]),consumptionRatio:num(row[b.c+6])},bev:{revenue:num(row[b.c+8]),purchases:num(row[b.c+9]),purchaseRatio:num(row[b.c+10]),consumption:num(row[b.c+11]),inventory:num(row[b.c+12]),consumptionRatio:num(row[b.c+13])}};}}
  const gr=shGrid(wb,'RÁCIOS MÊS A MÊS');if(gr){for(const[t,k] of [['FOOD COST','food'],['BEVERAGE COST','bev']]){const p=findCell(gr,v=>norm(v)===t);if(!p)continue;let hd=null;for(let r=p.r;r<Math.min(gr.length,p.r+8);r++){const c=(gr[r]||[]).findIndex(v=>norm(v)==='MESES');if(c>=0){hd={r,c};break;}}if(!hd)continue;const hcols=[];for(let c=hd.c+1;c<(gr[hd.r]||[]).length;c++){const h=canonHotel(gr[hd.r][c]);if(!h||h.startsWith('MEDIA'))break;if(D.hotels.includes(h))hcols.push({h,c});}D.ratios[k]={hotels:{}};hcols.forEach(x=>D.ratios[k].hotels[x.h]=Array.from({length:12},(_,i)=>num(gr[hd.r+1+i]?.[x.c])));}}
  const gd=shGrid(wb,'DADOS DIVERSOS');if(gd&&D.hotels.length){const hd=findCell(gd,v=>canonHotel(v)===D.hotels[0],10);if(hd){const hcols=[];for(let c=hd.c;c<(gd[hd.r]||[]).length;c++){const h=canonHotel(gd[hd.r][c]);if(!h)break;if(D.hotels.includes(h))hcols.push({h,c});}const map={'PA':'pa','COUVERTS':'couverts','DORMIDAS':'overnights','CONSUMOS INTERNOS COMIDAS':'internalFood','CONSUMOS INTERNOS BEBIDAS':'internalBev','REFEITORIO COMIDAS':'staffFood','REFEITORIO BEBIDAS':'staffBev','RECEITAS COMIDAS':'foodRevenue','RECEITAS BEBIDAS TOTAL':'bevRevenue'};for(const row of gd.slice(hd.r+1)){const key=map[norm(row?.[0])];if(!key)continue;D.diverse[key]={};hcols.forEach(x=>D.diverse[key][x.h]=num(row[x.c]));}}}
  const matrix=(name)=>{const g=shGrid(wb,name);if(!g||!D.hotels.length)return{};const hd=findCell(g,v=>canonHotel(v)===D.hotels[0],10);if(!hd)return{};const hcols=[];for(let c=hd.c;c<(g[hd.r]||[]).length;c++){const h=canonHotel(g[hd.r][c]);if(!h)break;if(D.hotels.includes(h))hcols.push({h,c});}const out={};for(const row of g.slice(hd.r+1)){const art=String(row?.[0]??'').trim();if(!art)continue;for(const x of hcols){const v=num(row[x.c]);if(v!=null){out[x.h]=out[x.h]||{};out[x.h][art]=v;}}}return out;};D.stock.initial=matrix('INVENTÁRIO INICIAL');D.stock.purchases=matrix('COMPRAS');D.stock.final=matrix('INVENTÁRIO FINAL');
  D.summaryGeneral={};D.monthly={food:{},bev:{}};D.accumulated={food:null,bev:null};
  const gg=shGrid(wb,'RESUMO GERAL');if(gg){const anchor=findCell(gg,v=>norm(v)==='CUSTO COMIDAS COUVERT');if(anchor){const hcols=[];for(let c=anchor.c+1;c<(gg[anchor.r]||[]).length;c++){const h=canonHotel(gg[anchor.r][c]);if(!h)break;if(D.hotels.includes(h))hcols.push({h,c});}const at=t=>{const z=findCell(gg,v=>norm(v)===norm(t));return z?z.r:-1;},read=(r0,r1)=>{const out={};for(let r=r0;r<(r1>0?r1:gg.length);r++){const lbl=String(gg[r]?.[anchor.c]??'').trim();if(!lbl)continue;out[lbl]={};hcols.forEach(x=>out[lbl][x.h]=num(gg[r]?.[x.c]));}return out;};const a=at('CUSTO COMIDAS/COUVERT + PA'),b=at('CUSTO TOTAL COMIDAS'),c=at('CUSTO BEBIDAS / PAX'),d=at('CUSTO TOTAL BEBIDAS'),e=at('FOOD COST');D.summaryGeneral.couvert=read(anchor.r+1,a);if(a>0)D.summaryGeneral.couvertPA=read(a+1,b);if(b>0)D.summaryGeneral.totalFood=read(b+1,c);if(c>0)D.summaryGeneral.bevPax=read(c+1,d);if(d>0)D.summaryGeneral.totalBev=read(d+1,e>0?e:d+6);}}
  const parseConsumption=name=>{const g=shGrid(wb,name);if(!g)return null;const a2=findCell(g,v=>norm(v)==='ARTIGOS',8);if(!a2)return null;const hcols=[];for(let c=a2.c+1;c<(g[a2.r]||[]).length;c++){const raw=String(g[a2.r]?.[c]??'').trim();if(!raw)break;const h=norm(raw)==='TOTAL'?'TOTAL':canonHotel(raw);if(h==='TOTAL'||D.hotels.includes(h))hcols.push({h,c});if(h==='TOTAL')break;}if(!hcols.length)return null;const totals=new Set(['TOTAL CONSUMO','PESO NO CUSTO','CUSTO POR COUVERT','CUSTO POR COUVERT PA','TOTAL COMPRAS','TOTAL INVENTARIO']),out={subfamilies:{},order:[]};let cur=null,has=false;for(let r=a2.r+1;r<g.length;r++){const row=g[r]||[],lbl=String(row[a2.c]??'').trim();if(!lbl)continue;const first=row[hcols[0].c];if(typeof first==='string'&&canonHotel(first)===hcols[0].h){cur=lbl;out.subfamilies[cur]={articles:{},order:[],totals:{}};out.order.push(cur);continue;}if(!cur)continue;const vals={};hcols.forEach(x=>vals[x.h]=num(row[x.c]));if(totals.has(norm(lbl)))out.subfamilies[cur].totals[lbl]=vals;else{out.subfamilies[cur].articles[lbl]=vals;out.subfamilies[cur].order.push(lbl);if(Object.values(vals).some(v=>v!=null&&Math.abs(v)>.005))has=true;}}return has?out:null;};
  const suff=['JAN','FEV','MAR','ABR','MAI','JUN','JUL','AGO','SET','OUT','NOV','DEZ'];for(let i=0;i<12;i++){const f=parseConsumption('Comidas_'+suff[i]),b=parseConsumption('Bebidas_'+suff[i]);if(f)D.monthly.food[i+1]=f;if(b)D.monthly.bev[i+1]=b;}D.accumulated.food=parseConsumption('Acumulado - Comidas');D.accumulated.bev=parseConsumption('Acumulado Bebidas');D.meta.months=Object.keys(D.monthly.food).map(Number).sort((a,b)=>a-b);return D;}
async function abLoadFile(file){if(!file)return;try{await window.VG?.performance?.ensureXLSX?.();const wb=XLSX.read(await file.arrayBuffer(),{type:'array'}),d=parseAbWorkbook(wb,file.name);d.id='ab-'+uid();state.ab.imports.unshift(d);state.ab.selected=d.id;persistLocal();renderAB();toast(`A&B: ${d.hotels.length} hotéis importados.`);window.VG?.events?.emit?.('ab:changed',{});}catch(e){toast('Custos A&B: '+e.message,true);}}
function abCurrent(){return state.ab.imports.find(x=>x.id===state.ab.selected)||state.ab.imports[0]||null;}
function abOverview(d){if(!d)return emptyCard('Sem mapa de Custos A&B','Importe o ficheiro mensal analisado pelo Departamento de Compras.');const hs=d.hotels,avg=k=>{const v=hs.map(h=>num(d.summary[h]?.[k])).filter(x=>x!=null);return v.length?sum(v)/v.length:null;};const subs=Object.entries(d.summaryGeneral?.couvert||{}).map(([name,vals])=>({name,avg:avgObj(vals)})).filter(x=>x.avg!=null).sort((a,b)=>b.avg-a.avg).slice(0,12);return `<div class="od-kpis"><article><span>Food Cost · consumo</span><strong>${fmt(avg('fcCons')*100,1)}%</strong><small>média simples unidades</small></article><article><span>Beverage Cost · consumo</span><strong>${fmt(avg('bcCons')*100,1)}%</strong><small>média simples unidades</small></article><article><span>Hotéis</span><strong>${hs.length}</strong><small>${esc(d.meta.fileName)}</small></article><article><span>Stock / pax</span><strong>${money(avg('stockPax'),2)}</strong><small>indicador do mapa</small></article></div><section class="od-card"><header><h3>Leitura por hotel</h3><span>compras vs consumo</span></header><div class="od-table-scroll"><table><thead><tr><th>Hotel</th><th>FC compras</th><th>FC consumo</th><th>BC compras</th><th>BC consumo</th><th>Consumo/pax</th><th>Stock/pax</th><th>Peso stock</th></tr></thead><tbody>${hs.map(h=>{const x=d.summary[h]||{};return `<tr><td>${esc(h)}</td><td>${pctVal(x.fcPurch)}</td><td>${pctVal(x.fcCons)}</td><td>${pctVal(x.bcPurch)}</td><td>${pctVal(x.bcCons)}</td><td>${money(x.consPax,2)}</td><td>${money(x.stockPax,2)}</td><td>${pctVal(x.stockWeight)}</td></tr>`}).join('')}</tbody></table></div></section>${subs.length?`<section class="od-card"><header><h3>Custo comidas / couvert por subfamília</h3><span>RESUMO GERAL · média das unidades no ficheiro</span></header>${subs.map(x=>bar(x.name,x.avg,Math.max(...subs.map(y=>y.avg),1),'',money(x.avg,2))).join('')}</section>`:''}`;}
function avgObj(o){const v=Object.values(o||{}).map(num).filter(x=>x!=null);return v.length?sum(v)/v.length:null;}
function abStock(d){if(!d)return emptyCard('Sem dados','');const hotels=d.hotels;let rows=[];for(const h of hotels){const arts=new Set([...Object.keys(d.stock.initial[h]||{}),...Object.keys(d.stock.purchases[h]||{}),...Object.keys(d.stock.final[h]||{})]);for(const a of arts){const ini=Number(d.stock.initial[h]?.[a]||0),buy=Number(d.stock.purchases[h]?.[a]||0),fin=Number(d.stock.final[h]?.[a]||0),cons=ini+buy-fin;rows.push({h,a,ini,buy,fin,cons});}}rows=rows.sort((a,b)=>Math.abs(b.cons)-Math.abs(a.cons)).slice(0,300);return `<section class="od-card"><header><h3>Stock &amp; consumo teórico por balanço</h3><span>Inventário inicial + compras - inventário final</span></header><div class="od-table-scroll"><table><thead><tr><th>Hotel</th><th>Artigo</th><th>Inv. inicial</th><th>Compras</th><th>Inv. final</th><th>Consumo</th></tr></thead><tbody>${rows.map(x=>`<tr><td>${esc(x.h)}</td><td>${esc(x.a)}</td><td>${fmt(x.ini,2)}</td><td>${fmt(x.buy,2)}</td><td>${fmt(x.fin,2)}</td><td>${fmt(x.cons,2)}</td></tr>`).join('')}</tbody></table></div></section>`;}

function recipesList(){
  const lib=state.seed?.technicalLibrary||{},all=[...(lib.recipes||[]),...(lib.products||[])].filter(x=>x.market===seedMarket());
  const q=norm(state.recipes.query), kind=state.recipes.kind||'all';
  return all.filter(x=>(kind==='all'||(kind==='recipes'&&x.kind!=='product')||(kind==='products'&&x.kind==='product'))&&
    (!q||norm([x.name,x.category,x.collection,x.brandScope,x.source,x.country,x.version,(x.ingredients||[]).map(i=>i.ingredient).join(' ')].join(' ')).includes(q)));
}
